"""Release dates for Python, Node and Postgres, and Docker Hub dates for the chosen image tags."""

import json
import urllib.request


def get(url: str) -> object:
    req = urllib.request.Request(url, headers={"User-Agent": "version-check", "Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)


try:
    rels = get("https://www.python.org/api/v2/downloads/release/?is_published=true")
    rows = sorted((r["release_date"][:10], r["name"]) for r in rels
                  if any(r["name"].startswith(f"Python 3.{m}") for m in (13, 14, 15)))
    print("python:", rows[-30:])
except Exception as e:
    print("python ERROR", e)

try:
    node = get("https://nodejs.org/dist/index.json")
    for major in ("v22.", "v24.", "v26."):
        top = [n for n in node if n["version"].startswith(major)][:3]
        print("node", major, [(n["version"], n["date"], n["lts"], n["security"]) for n in top])
except Exception as e:
    print("node ERROR", e)

try:
    pg = get("https://www.postgresql.org/versions.json")
    print("postgres:", [(v.get("major"), v.get("latestMinor"), v.get("relDate"), v.get("eolDate"), v.get("current"), v.get("supported")) for v in pg][:6])
except Exception as e:
    print("postgres ERROR", e)

for image, tag in [("library/python", "3.13.16-slim-trixie"), ("library/python", "3.13.15-slim-trixie"),
                   ("library/python", "3.14.8-slim-trixie"), ("library/python", "3.15.0-slim-trixie"),
                   ("library/node", "24.22.0-alpine3.24"), ("library/node", "24.21.0-alpine3.24"),
                   ("library/node", "26.12.0-alpine3.24"), ("library/postgres", "17.11-alpine3.24"),
                   ("library/postgres", "17.10-alpine3.24"), ("library/postgres", "18.6-alpine3.24"),
                   ("library/postgres", "19"), ("library/postgres", "19.0-alpine3.24"),
                   ("nginxinc/nginx-unprivileged", "1.30.5-alpine3.24"), ("nginxinc/nginx-unprivileged", "1.30.6-alpine3.24"),
                   ("grafana/k6", "2.3.0"), ("grafana/k6", "1.8.2"), ("astral/uv", "0.12.23"), ("astral/uv", "0.12.24")]:
    try:
        t = get(f"https://hub.docker.com/v2/repositories/{image}/tags/{tag}")
        print(f"{image}:{tag} last_updated={t['last_updated'][:10]} digest={t.get('digest', '')[:19]}")
    except Exception as e:
        print(f"{image}:{tag} ERROR {e}")

